package com.demo.catalog;

@Service
public class ProductService {
    private final ProductMapper productMapper;
    private final StringRedisTemplate redisTemplate;

    public ProductDetail getProduct(Long productId) {
        String key = "product:" + productId;
        String cached = redisTemplate.opsForValue().get(key);
        if (cached != null) {
            return Json.parse(cached, ProductDetail.class);
        }
        ProductDetail detail = productMapper.findDetail(productId);
        redisTemplate.opsForValue().set(key, Json.stringify(detail));
        return detail;
    }
}
